package dev.arabicgames.phone;
import android.app.Activity;import android.os.Bundle;import android.widget.*;
public final class TimingActivity extends Activity {
 private SeekBar frame,settle,age;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);root.setPadding(20,20,20,20);root.addView(Ui.text(this,"سرعة القراءة — QuickMT وجسر والمحلي",24));root.addView(Ui.text(this,"الفاصل الأقل يقرأ الحوار أسرع لكنه يستهلك طاقة أكثر. الاستقرار الأقل يقلل الانتظار وقد يلتقط كلمات ناقصة. هذه الخيارات لا تسرّع حساب النموذج نفسه. حد عمر السطر يمنع عرض ترجمة قديمة؛ ليس تأخيرًا نضيفه للترجمة.",16));
 frame=slider(root,"فاصل قراءة الفيديو",100,600,LocalTiming.interval(this));settle=slider(root,"انتظار استقرار النص",0,400,LocalTiming.settle(this));age=slider(root,"أقصى عمر للسطر قبل تجاهل عرضه",1000,6000,LocalTiming.maxAge(this));
 Ui.button(this,root,"سريع — ابدأ بهذا",true,()->preset(150,80,4500));Ui.button(this,root,"أسرع قراءة — استهلاك أعلى",false,()->preset(100,0,4500));Ui.button(this,root,"اقتصادي — طاقة وحرارة أقل",false,()->preset(350,180,4500));Ui.button(this,root,"حفظ وتطبيق",true,()->{LocalTiming.save(this,frame.getProgress()+100,settle.getProgress(),age.getProgress()+1000);Status.message="تم تطبيق إعدادات القراءة المحلية.";finish();});Ui.button(this,root,"رجوع",false,this::finish);ScrollView scroll=new ScrollView(this);scroll.addView(root);PhoneInsets.fit(scroll);setContentView(scroll);}
 private void preset(int f,int s,int a){frame.setProgress(f-100);settle.setProgress(s);age.setProgress(a-1000);}
 private SeekBar slider(LinearLayout root,String name,int min,int max,int value){TextView label=Ui.text(this,name+": "+value+" ms",16);root.addView(label);SeekBar bar=new SeekBar(this);bar.setMax(max-min);bar.setProgress(value-min);bar.setMinimumHeight(Ui.dp(this,48));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){label.setText(name+": "+(v+min)+" ms");}});root.addView(bar);return bar;}
}
